#define TWOPI 710./113.

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/min(iResolution.y, iResolution.x);
    uv *= 5.;
    vec2 polar = vec2(
        length(uv),
        atan(uv.y, uv.x)
    );

    float maxangle = TWOPI / 9.;

    polar.y = mod(polar.y + maxangle*.5, maxangle) - maxangle*.5;

    uv = polar.x * vec2(cos(polar.y), sin(polar.y));

    uv.y = abs(uv.y);

    vec2 dir = normalize(vec2(1., mix(0.1, 0.3, 0.5+0.5*sin(iTime))));
    uv -= dir * max(0., 2.*dot(dir, uv - vec2(0.25, 0.0)));
    uv.y = abs(uv.y);

    dir = normalize(vec2(1., 0.3));
    uv -= dir * max(0., 2.*dot(dir, uv - vec2(0.1, 0.0)));
    uv.y = abs(uv.y);

    dir = normalize(vec2(1., -.5));
    uv -= dir * min(0., 2.*dot(dir, uv - vec2(-.5, 0.0)));
    uv.y = abs(uv.y);

    float f = smoothstep(0.01,0.0,uv.y);

    // Time varying pixel color
    vec3 col = 3. * mix(smoothstep(0.5, 1.0, 1.-uv.y),f,0.6)*(0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4)))*texture(iChannel0, uv-0.2*iTime).rgb;

    // Output to screen
    fragColor = vec4(col,1.0);
}
